objectCard.openingEventHandler:

  const handler = async () => {
    try {
      const { positions } = await ESS.network.sendRequest('/api/functions/EssBase_GetPositionListByPerson');
      if (positions.length > 1) {
        const initiator = positions.find(({ id }) => String(id) === String(data.author));
        if (initiator) {
          data.initiator = {
            FullName: g_userPerson.name,
            Position: initiator.title,
            Department: initiator.department,
            Organization: initiator.organization,
          };
        } else {
          throw new Error(ESS.L('@ESSBASE.INITIATOR_NOT_FOUND'));
        }
      }
    } catch (error) {
      console.warn(ESS.L('@ESSBASE.GET_INITIATOR_ERROR'), error);
    }
    resolve(data);
  };
  handler();

objectCard.openedEventHandler:

  const inactiveStatuses = [
    ESS.enums.WorkProcessStatus.ABORTED,
    ESS.enums.WorkProcessStatus.DRAFT,
    ESS.enums.WorkProcessStatus.COMPLETED,
    ESS.enums.WorkProcessStatus.SUSPENDED,
  ];
  if (inactiveStatuses.includes(data.status)) {
    functions.setVisibility('abort', ESS.enums.Visibility.HIDDEN);
  }
  resolve({ configuration, data });
